# scrapy 用 Spider 類別定義怎麼爬
class MySpider(scrapy.Spider):
    def parse(self, response):
        yield {'title': response.css('h1::text').get()}

import typer
def main(name: str, count: int = 1):
    for _ in range(count): print(f'Hi {name}')
typer.run(main)   # 自動變成 CLI

